input.query:
SELECT DATE_DIFF('day', inception_date, expiry_date) AS len, COUNT(*) n, SUM(CASE WHEN cancel_date IS NOT NULL THEN 1 ELSE 0 END) cancelled
FROM policy_term WHERE vehicle_group='E' AND inception_date <= DATE '2023-12-31' AND expiry_date >= DATE '2023-01-01'
GROUP BY len ORDER BY n DESC LIMIT 10;
